import math

def is_prime(n):
    """Checks if a number n is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_perfect_cube(n):
    """Checks if n is a perfect cube and returns its integer cube root."""
    if n < 0:
        return None

    # Estimate the cube root using floating point
    root = round(n**(1/3))

    # Check if the cube of the rounded root equals n
    if root * root * root == n:
        return root
    return None

# List of primes up to 150
primes = []
for n in range(2, 151):
    if is_prime(n):
        primes.append(n)

solutions = []
print("Starting search...")

for q in primes:
    # Calculate N = q^2 - q + 1
    N = q*q - q + 1

    # Check if N is a perfect cube P^3
    P = is_perfect_cube(N)

    if P is not None:
        # Check conditions: P must be prime and P != q
        if is_prime(P) and P != q:
